var u=["JAN","FEB","MAR","APR","MAY","JUN","JUL","AUG","SEP","OCT","NOV","DEC"];function s(t){if(!t)return"\u2014";let n=typeof t=="string"?new Date(t):t;return Number.isNaN(n.getTime())?"\u2014":`${n.getUTCDate()} ${u[n.getUTCMonth()]} ${n.getUTCFullYear()}`}function a(t){if(!t)return"\u2014";let n=new Date(t);if(Number.isNaN(n.getTime()))return"\u2014";let e=String(n.getHours()).padStart(2,"0"),r=String(n.getMinutes()).padStart(2,"0");return`${s(n)} ${e}:${r}`}function l(t,n){if(!t)return"\u2014";let e=new Date(t),r=`${u[e.getUTCMonth()]} ${e.getUTCFullYear()}`;if(!n)return`${r}\u2013PRESENT`;let i=new Date(n);return`${r}\u2013${u[i.getUTCMonth()]} ${i.getUTCFullYear()}`}function g(t){if(!t)return"\u2014";let n=new Date(t).getTime();if(Number.isNaN(n))return"\u2014";let e=Math.round((Date.now()-n)/1e3);if(e<60)return"just now";let r=Math.round(e/60);if(r<60)return`${r}m ago`;let i=Math.round(r/60);if(i<24)return`${i}h ago`;let o=Math.round(i/24);return o<30?`${o}d ago`:s(t)}function c(t){if(!t)return null;let n=new Date(t).getTime();return Number.isNaN(n)?null:Math.max(0,Math.floor((Date.now()-n)/864e5))}function f(t){if(!t||t<0)return"\u2014";let n=["B","KB","MB","GB"],e=t,r=0;for(;e>=1024&&r<n.length-1;)e/=1024,r++;return`${e<10&&r>0?e.toFixed(1):Math.round(e)} ${n[r]}`}function d(t){return t?t.replaceAll("_"," ").replaceAll("-"," ").toUpperCase():"\u2014"}function h(t){return t.trim().split(/\s+/).slice(0,2).map(n=>n.charAt(0)).join("").toUpperCase()||"?"}function p(t){return"0x"+t.replace(/-/g,"").slice(0,4).toUpperCase()}export{s as a,a as b,l as c,g as d,c as e,f,d as g,h,p as i};
